#!/usr/bin/env bash
# Phase 4: public HTTPS/WSS via Caddy and production token verification.
# Prerequisites: DNS A record api.syntila.app -> this server (DNS only),
# infra/vps/auth-public-keys.json generated by generate-signing-key.mjs.
# Usage (on the VPS):  sudo bash ~/phase3-stage/vps/install-phase4.sh
set -Eeuo pipefail
export LC_ALL=C.UTF-8 LANG=C.UTF-8   # silence perl/apt locale warnings from macOS SSH sessions
if [ "$(id -u)" -ne 0 ]; then echo 'Run with sudo.' >&2; exit 1; fi
stage=/home/syntila/phase3-stage
host=api.syntila.app
for path in "$stage/vps/Caddyfile" "$stage/vps/auth-public-keys.json" "$stage/vps/install-phase3.sh"; do
  [ -f "$path" ] || { echo "Missing $path" >&2; exit 1; }
done
python3 - "$stage/vps/auth-public-keys.json" <<'PY'
import json, sys
keys = json.load(open(sys.argv[1]))
assert isinstance(keys, list) and keys, "expected a non-empty JWK array"
for k in keys:
    assert k.get("kty") == "OKP" and k.get("crv") == "Ed25519" and k.get("kid") and k.get("x"), "bad key"
    assert "d" not in k, "PRIVATE key found in auth-public-keys.json - do not upload it"
print(f"{len(keys)} public key(s) OK")
PY

echo "== DNS check for $host"
public_ip=$(curl -4 -fsS --max-time 5 https://api.ipify.org || true)
dns_ip=$(getent ahostsv4 "$host" | awk 'NR==1{print $1}')
echo "server: ${public_ip:-unknown}  dns: ${dns_ip:-none}"
if [ -z "$dns_ip" ] || { [ -n "$public_ip" ] && [ "$dns_ip" != "$public_ip" ]; }; then
  echo "DNS for $host must point to this server (Cloudflare: A record, DNS only / grey cloud). Fix it and re-run." >&2
  exit 1
fi

echo '== Deploy latest backend release'
bash "$stage/vps/install-phase3.sh"

echo '== Production auth keys'
install -m 0600 -o root -g root "$stage/vps/auth-public-keys.json" /etc/syntila/auth-public-keys
sed -i 's#^AUTH_JWT_ISSUER=.*#AUTH_JWT_ISSUER=https://syntila.app#; s#^ALLOWED_ORIGINS=.*#ALLOWED_ORIGINS=https://syntila.app#' /etc/syntila/backend.env
if [ -d /home/syntila/dev-auth ]; then
  shred -u /home/syntila/dev-auth/* 2>/dev/null || rm -f /home/syntila/dev-auth/*
  rmdir /home/syntila/dev-auth
  echo 'Development signing key deleted.'
fi
systemctl restart syntila-backend
for attempt in $(seq 1 30); do curl -fsS --max-time 2 http://127.0.0.1:3000/health/ready >/dev/null 2>&1 && break; sleep 1; done
echo "Backend: $(curl -sS http://127.0.0.1:3000/health/ready)"

echo '== Caddy'
# Ubuntu ships Caddy 2.6 (2022); use the official repository for current, patched releases.
caddy_ok() { command -v caddy >/dev/null && caddy version | grep -Eq '^v?2\.([7-9]|[1-9][0-9])\.'; }
if ! caddy_ok; then
  apt-get install -y -qq debian-keyring debian-archive-keyring apt-transport-https curl gpg >/dev/null
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/gpg.key' | gpg --dearmor --yes -o /usr/share/keyrings/caddy-stable-archive-keyring.gpg
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/debian.deb.txt' > /etc/apt/sources.list.d/caddy-stable.list
  chmod o+r /usr/share/keyrings/caddy-stable-archive-keyring.gpg /etc/apt/sources.list.d/caddy-stable.list
  printf 'Package: caddy\nPin: origin dl.cloudsmith.io\nPin-Priority: 1001\n' > /etc/apt/preferences.d/caddy-official
  apt-get update -qq
  apt-get install -y -qq caddy
fi
caddy_ok || { echo "Caddy >= 2.7 required, found: $(caddy version)" >&2; exit 1; }
caddy version
[ -f /etc/caddy/Caddyfile ] && cp /etc/caddy/Caddyfile "/etc/caddy/Caddyfile.bak.$(date +%s)"
install -m 0644 -o root -g root "$stage/vps/Caddyfile" /etc/caddy/Caddyfile
install -d -o caddy -g caddy /var/log/caddy
caddy validate --config /etc/caddy/Caddyfile --adapter caddyfile
ufw allow 443/udp comment 'HTTP/3' >/dev/null
systemctl enable caddy >/dev/null
systemctl reload-or-restart caddy

echo "== Public check (certificate issuance can take ~30 s)"
for attempt in $(seq 1 30); do
  if curl -fsS --max-time 5 "https://$host/health/live" >/dev/null 2>&1; then break; fi
  sleep 2
done
echo "https://$host/health/live  -> $(curl -sS --max-time 5 https://$host/health/live || echo FAILED)"
echo "https://$host/health/ready -> $(curl -sS --max-time 5 https://$host/health/ready || echo FAILED)"
code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 5 "https://$host/api/spaces")
echo "https://$host/api/spaces without token -> $code (expected 401)"
journalctl -u caddy -n 5 --no-pager | grep -i -E 'error|certificate' || true
